  ["Route11_Text_BernieRematchIntro"] = "¡Cuidado con esos cables!",
  ["Route11_Text_BraxtonRematchIntro"] = "¡Eh, tú!\\p¡Cuidado!\\n¡Estoy colocando unos cables!",
  ["Route11_Text_DarianRematchIntro"] = "Nunca he ganado...\\p¿Será mi destino?",
  ["Route11_Text_DaveRematchIntro"] = "¡Mis POKéMON ya deberían estar\\nlistos! ¡Esta vez hay que ganar!",
  ["Route11_Text_DillonRematchIntro"] = "¡Soy un nuevo ENTRENADOR!\\n¡Pero creo que no tengo problema\\lpara ganar!",
  ["Route11_Text_DirkRematchIntro"] = "¡Ja, ja, ja!\\n¡No he perdido nunca!\\p¡Y si he perdido alguna vez,\\nno me acuerdo!",
  ["Route11_Text_EddieRematchIntro"] = "¿Luchamos otra vez?\\n¡Vamos allá, pero no hagas\\ltrampas!",
  ["Route11_Text_HugoRematchIntro"] = "¡Gana, pierde o empata!\\n¡Pero lucha de nuevo!",
  ["Route11_Text_JasperRematchIntro"] = "¡Competir es lo más!\\n¡Yo no me canso de competir!",
  ["Route11_Text_YasuRematchIntro"] = "¡Soy el mejor de mi clase!\\n¡Me entreno día y noche!",
