  ["Route12_Text_AndrewRematchIntro"] = "¿No sabes cómo pescar?\\p¡Te lo explicaré cuando acabe\\ncontigo!",
  ["Route12_Text_ChipRematchIntro"] = "¡Aquí estás otra vez!\\n¡Pescar requiere tiempo!",
  ["Route12_Text_ElliotRematchIntro"] = "A mí me encanta pescar, pero no\\nes nada fácil que piquen, ¿sabes?",
  ["Route12_Text_GiaRematchIntro"] = "AGA: Oye, ARE, estoy aburrida\\nde esperar...\\pSi ganamos, ¡me caso contigo!",
  ["Route12_Text_HankRematchIntro"] = "¡El PESCADOR LOCO contra alguien\\nque no tiene idea sobre POKéMON!\\l¡Lucha, venga!",
  ["Route12_Text_JesRematchIntro"] = "ARE: Voy a ganar y a pedirle a\\nAGA que se case conmigo.",
  ["Route12_Text_JustinRematchIntro"] = "Sigo sin PIEDRA LUNAR...\\n¿Tienes tú una?",
  ["Route12_Text_LucaRematchIntro"] = "¡Soy un experto en electricidad!\\pPero de los POKéMON de agua\\nsé poca cosa...",
  ["Route12_Text_NedRematchIntro"] = "¡Bien!\\n¡Ha picado algo!\\l¡Esta vez seguro que es bueno!",
  ["Route13_Text_AlmaRematchIntro"] = "Me he gastado mis ahorros\\ncomprando más CARBURANTE.",
  ["Route13_Text_GwenRematchIntro"] = "Mis simpáticos POKéMON quieren\\nvolver a verte.",
  ["Route13_Text_JaredRematchIntro"] = "¿Qué miras?",
  ["Route13_Text_LolaRematchIntro"] = "Has vuelto...\\pPor supuesto que lucharé\\notra vez contigo.",
  ["Route13_Text_PerryRematchIntro"] = "¡Esta vez no pienso perder!\\n¡El viento sopla en mi dirección!",
  ["Route13_Text_RobertRematchIntro"] = "¡Me encantan los pájaros POKéMON!\\n¡Siempre me he dedicado a ellos!",
  ["Route13_Text_SebastianRematchIntro"] = "¡Mis pájaros POKéMON se acuerdan\\nde ti!",
  ["Route13_Text_SheilaRematchIntro"] = "¿No te acuerdas de que luchamos\\nen otra ocasión?",
  ["Route13_Text_SusieRematchIntro"] = "Quiero ser la mejor ENTRENADORA\\nsiendo todavía pequeña.",
  ["Route13_Text_ValerieRematchIntro"] = "¡Guau!\\n¡Qué chulas son tus MEDALLAS!",
  ["Route14_Text_BeckRematchIntro"] = "¿Usas MT con tus POKéMON?\\nTenerlas en la MOCHILA sin más\\lno sirve para nada.",
  ["Route14_Text_BennyRematchIntro"] = "¡No me apetece luchar,\\npero lo haré!",
  ["Route14_Text_CarterRematchIntro"] = "He usado mis MT para enseñarles\\nbuenos movimientos a mis POKéMON.",
  ["Route14_Text_DonaldRematchIntro"] = "¿Llegaste a oír hablar de los\\nmisteriosos seres alados?",
  ["Route14_Text_GeraldRematchIntro"] = "¡Nos gusta pedalear por aquí\\nporque hay mucho espacio!",
  ["Route14_Text_IsaacRematchIntro"] = "Aquí estás otra vez, ¿eh?\\n¡Bueno, así pasaré el rato!",
  ["Route14_Text_JanRematchIntro"] = "TEA: LENA, ¡vamos allá!\\n¡Tenemos que ganar!",
  ["Route14_Text_KiriRematchIntro"] = "LENA: TEA, a ver si ganamos.",
  ["Route14_Text_LukasRematchIntro"] = "¡Eh, me acuerdo de ti!\\p¡Venga, venga!\\n¡Vamos, vamos! ¡Adelante!",
  ["Route14_Text_MalikRematchIntro"] = "¿Quieres pelear con tus POKéMON?\\n¡Pues vale, vamos allá!",
  ["Route14_Text_MarlonRematchIntro"] = "¿Has enseñado a VOLAR a tus\\npájaros POKéMON?\\pDeberías hacerlo y disfrutar de\\nla maravillosa vista.",
  ["Route14_Text_MitchRematchIntro"] = "Mis pájaros POKéMON deberían\\nluchar bien esta vez.",
  ["Route15_Text_AlexRematchIntro"] = "¡Mira, colega, si pierdes contra\\nmí, todo tu dinero será mío!",
  ["Route15_Text_BeckyRematchIntro"] = "¡Creo que puedo contigo!\\n¡Voy a intentar vencerte!",
  ["Route15_Text_CeliaRematchIntro"] = "¿Qué mola?\\n¡Cambiar POKéMON, claro!",
  ["Route15_Text_ChesterRematchIntro"] = "Mis pájaros están temblando.\\n¡Ya te conocen!",
  ["Route15_Text_EdwinRematchIntro"] = "Cuando silbo, acuden varios\\npájaros POKéMON.\\p¡Son monísimos!",
  ["Route15_Text_ErnestRematchIntro"] = "¡Oye! ¡Ven aquí!\\n¡Mira esto!",
  ["Route15_Text_GraceRematchIntro"] = "¡Oh!\\n¡Mira qué encanto!\\l¡Anda, yo a ti te conozco!",
  ["Route15_Text_KindraRematchIntro"] = "¡Déjame probar los POKéMON\\nque me han enviado!",
  ["Route15_Text_MyaRematchIntro"] = "TINA: ¡Volvemos a vernos!\\p¿Luchamos para que aprenda\\nmi hermano?",
  ["Route15_Text_OliviaRematchIntro"] = "¡Cuido POKéMON porque sigo\\nviviendo sola!",
  ["Route15_Text_RonRematchIntro"] = "TIN: Mi hermana es la más fuerte.",
  ["Route15_Text_YazminRematchIntro"] = "¿Quieres jugar con mis POKéMON\\notra vez?",
  ["Route16_Text_CamronRematchIntro"] = "¡Tengo hambre y sigo sin estar\\nde humor!",
  ["Route16_Text_HideoRematchIntro"] = "¡Oye! ¡Me has golpeado!\\n¡Ahora tendrás que luchar conmigo!",
  ["Route16_Text_JedRematchIntro"] = "JOEL: ¿Vienes para comprobar que\\nnuestro amor no conoce límites?",
  ["Route16_Text_KojiRematchIntro"] = "¡Bonita BICI!\\n¡Dámela ahora mismo!",
  ["Route16_Text_LaoRematchIntro"] = "¿Qué quieres?",
  ["Route16_Text_LeaRematchIntro"] = "LIZ: ¡A veces, pienso en todo\\nlo que nos queremos y se me pone\\lla carne de gallina!",
  ["Route16_Text_LukeRematchIntro"] = "¡Baja de ahí y lucha, enclenque!\\n¡Te vas a enterar!",
  ["Route16_Text_RubenRematchIntro"] = "¡Eh, vamos a echar otro rato!",
  ["Route17_Text_BillyRematchIntro"] = "¡Somos los MOTORISTAS!\\n¡Las estrellas de la autopista!",
  ["Route17_Text_CoreyRematchIntro"] = "¡Sé rebelde!",
  ["Route17_Text_IsaiahRematchIntro"] = "¿Y tú qué quieres?",
  ["Route17_Text_JamalRematchIntro"] = "¡Necesito un poco de ejercicio\\ny bajar peso!",
  ["Route17_Text_JaxonRematchIntro"] = "¡Tienes una BICI muy guay!\\n¿Cómo se conduce?",
  ["Route17_Text_NikolasRematchIntro"] = "Mis VOLTORB van a darte\\nun calambrazo.",
  ["Route17_Text_RaulRematchIntro"] = "¡Ya te dije que no compensaba\\nluchar con niños!",
  ["Route17_Text_VirgilRematchIntro"] = "¿Qué vas, de paseo?",
  ["Route17_Text_WilliamRematchIntro"] = "¡Lárgate!\\n¡Estoy agotado!",
  ["Route17_Text_ZeekRematchIntro"] = "¡Mi POKéMON no evoluciona!\\nNo acabo de entender por qué.",
  ["Route18_Text_JacobRematchIntro"] = "¡Es mi césped!\\n¡Fuera de aquí!\\p¡No quiero volver a verte por\\naquí!",
  ["Route18_Text_RamiroRematchIntro"] = "¡Cucu, cucu! ¿Ha mejorado\\nel reclamo de mi pájaro?",
  ["Route18_Text_WiltonRematchIntro"] = "Compruebo siempre las zonas de\\nhierba en busca de nuevos POKéMON.\\pPero no siempre encuentro...",
  ["Route19_Text_AliceRematchIntro"] = "¡Nadar es genial! ¡Pero no me\\ngusta quemarme al sol!",
  ["Route19_Text_AnyaRematchIntro"] = "¡Me encanta el POKéMON con\\nel que estás haciendo SURF.\\p¿Me lo darás si gano?",
  ["Route19_Text_AxleRematchIntro"] = "¡Estas aguas son traicioneras!\\n¡No deberías volver por aquí!",
  ["Route19_Text_ConnieRematchIntro"] = "He venido nadando hasta aquí,\\npero ya me he cansado.\\p¿De verdad tenemos que luchar\\notra vez?",
  ["Route19_Text_DavidRematchIntro"] = "¡He buceado en busca de POKéMON,\\npero sigo sin ver nada!",
  ["Route19_Text_DouglasRematchIntro"] = "¿Qué hay más allá del horizonte?\\n¿Lo sabes?",
  ["Route19_Text_LiaRematchIntro"] = "CATI: Ya sabes que mi hermano\\nacaba de hacerse ENTRENADOR.\\pVamos a luchar para que mejore\\nsu técnica, ¿vale?",
  ["Route19_Text_LucRematchIntro"] = "TEC: Mi hermana mayor me ha\\nenseñado mucho sobre POKéMON.\\p¿Soy mejor ahora?",
  ["Route19_Text_MatthewRematchIntro"] = "¡Me gusta nadar!\\nSeguro que a ti también.",
  ["Route19_Text_ReeceRematchIntro"] = "¡Alto!\\n¡Oye, que te va a dar algo!",
  ["Route19_Text_RichardRematchIntro"] = "Estaba a punto de darme un baño.",
  ["Route19_Text_TonyRematchIntro"] = "¡Miro al mar para olvidar!\\pQuiero olvidarme de cuando perdí\\ncontigo.",
  ["Route20_Text_BarryRematchIntro"] = "El agua es poco profunda aquí.",
  ["Route20_Text_DarrinRematchIntro"] = "¿Por qué te has subido a un\\nPOKéMON? ¿Aún no sabes nadar?",
  ["Route20_Text_DeanRematchIntro"] = "¡Mira que cuerpazo tengo!\\p¡Estoy mejor que antes!",
  ["Route20_Text_IreneRematchIntro"] = "¿Tú también estabas de vacaciones?",
  ["Route20_Text_MelissaRematchIntro"] = "En ISLA CANELA, al oeste, hay\\nun LABORATORIO POKéMON.\\pMi padre trabaja allí.",
  ["Route20_Text_MissyRematchIntro"] = "Vine nadando desde ISLA\\nCANELA. Fue agotador.",
  ["Route20_Text_NoraRematchIntro"] = "¡Mi novio me dio unas perlas\\nmuy grandes!\\p¡Y ahora están más grandes aún!",
  ["Route20_Text_RogerRematchIntro"] = "¡Ha venido sobre uno de mis\\npájaros POKéMON!",
  ["Route20_Text_ShirleyRematchIntro"] = "¿Te da envidia que esté de\\nvacaciones en las ISLAS ESPUMA?",
  ["Route20_Text_TiffanyRematchIntro"] = "¡Me gusta flotar en el agua\\nrodeada de peces!",
  ["Route21_North_Text_CueBallRematchIntro"] = "Ê;Âó Èù?à\\nÊÙ??Œ?",
  ["Route21_North_Text_IanRematchIntro"] = "IGOR: Mi hermana es un pelín vaga,\\n¡pero si hay que luchar, hay que\\lluchar!",
  ["Route21_North_Text_LilRematchIntro"] = "ÍA: ¿Cómo, que quieres luchar otra\\nvez? IGOR, ¿cómo lo ves?",
  ["Route21_North_Text_RonaldRematchIntro"] = "¿Quieres saber si los peces pican?",
  ["Route21_North_Text_SpencerRematchIntro"] = "¡El mar limpia mi cuerpo y mi\\nalma!",
  ["Route21_North_Text_WadeRematchIntro"] = "¡Tengo una gran red!\\n¿Quieres probarla otra vez?",
  ["Route21_South_Text_ClaudeRematchIntro"] = "¡Eh!\\n¡Siempre asustas a los peces!",
  ["Route21_South_Text_JackRematchIntro"] = "¡He conseguido a mi POKéMON\\nen el mar, y aquí lo entreno!",
  ["Route21_South_Text_JeromeRematchIntro"] = "¡Ahora estoy en otro encuentro\\nde triatlón!",
  ["Route21_South_Text_NolanRematchIntro"] = "¡Quédate conmigo hasta que lo\\nconsiga!",
  ["Route21_South_Text_RolandRematchIntro"] = "¡Ah!\\n¡Siente el sol y el viento!",
  ["Route24_Text_AliRematchIntro"] = "Aunque perdí cuando luchamos,\\nestuvo guay, ¿verdad?",
  ["Route24_Text_CaleRematchIntro"] = "Éste es el PUENTE PEPITA.\\pYa nos has machacado a todos,\\nasí que ya te puedes marchar...\\pAunque... no me importaría\\nvolver a enfrentarme a ti.",
  ["Route24_Text_EthanRematchIntro"] = "¡Muy bien, voy a acabar contigo!",
  ["Route24_Text_ReliRematchIntro"] = "Siempre estás de aquí para allá...\\n¿No te cansas?",
  ["Route24_Text_ShaneRematchIntro"] = "¡Vi tu hazaña desde la hierba!",
  ["Route24_Text_TimmyRematchIntro"] = "Se ve que te encanta venir\\nal PUENTE PEPITA.",
  ["Route25_Text_ChadRematchIntro"] = "¡Sabía que tendría que luchar\\ncontigo otra vez!",
  ["Route25_Text_DanRematchIntro"] = "¡Mi padre me llevó a una gran\\nfiesta en el S.S. ANNE, en\\lCIUDAD CARMÍN!",
  ["Route25_Text_FlintRematchIntro"] = "Soy un buen chico.\\n¡Y tengo novia!\\p¡Verás cómo se queda cuando\\nme vea luchar esta vez!",
  ["Route25_Text_FranklinRematchIntro"] = "¡Acabo de bajar del MT. MOON,\\npero estoy listo!",
  ["Route25_Text_HaleyRematchIntro"] = "Mi amigo tiene POKéMON muy\\nmonos. ¡Qué envidia!",
  ["Route25_Text_JoeyRematchIntro"] = "¡No pienso perder!",
  ["Route25_Text_KelseyRematchIntro"] = "¡Hola!\\n¡Mi chico es genial!\\l¡Y hoy me encuentro en forma!",
  ["Route25_Text_NobRematchIntro"] = "¡Hay un POKéMANÍACO viviendo\\nen el cabo!\\p¿Has visto la colección que tiene?",
  ["Route25_Text_WayneRematchIntro"] = "¿Vas a ver a BILL otra vez?\\n¡Pues luchemos primero!",
  ["Route3_Text_BenRematchIntro"] = "¡Hola!\\n¡Me gustan los pantalones cortos!\\p¡Son muy cómodos!",
  ["Route3_Text_CalvinRematchIntro"] = "¡Oye!\\n¡No llevas pantalón corto!",
  ["Route3_Text_ColtonRematchIntro"] = "¡Nos vimos en el BOSQUE VERDE!",
  ["Route3_Text_GregRematchIntro"] = "¿Entrenas POKéMON?\\n¡Pues luchemos!",
  ["Route3_Text_JamesRematchIntro"] = "Lucharé contigo junto a los\\nPOKéMON que yo mismo he criado.",
  ["Route3_Text_JaniceRematchIntro"] = "Estabas mirándome ¿verdad?",
  ["Route3_Text_RobinRematchIntro"] = "¡Eh!\\n¡Me has empujado!",
  ["Route3_Text_SallyRematchIntro"] = "¡Esa mirada tuya fue de lo más\\nmisteriosa!",
  ["Route4_Text_CrissyRematchIntro"] = "A mí me encanta buscar POKéMON\\nhongo en el MT. MOON.",
  ["Route6_Text_ElijahRematchIntro"] = "Eh, ¡qué de tiempo!\\n¿Eres más fuerte?",
  ["Route6_Text_IsabelleRematchIntro"] = "¿Yo?\\nPues vale. ¡Vamos!",
  ["Route6_Text_JeffRematchIntro"] = "¿Qué? ¿Qué quieres, luchar\\nconmigo de nuevo?",
  ["Route6_Text_KeigoRematchIntro"] = "Estoy intentando encontrar un buen\\nejemplar, que no sea un POKéMON\\lBICHO, pero...",
  ["Route6_Text_NancyRematchIntro"] = "Perdona, ¿no ves que es una\\nconversación privada?\\pPues ¿qué haces con la antena\\npuesta?",
  ["Route6_Text_RickyRematchIntro"] = "¡Tu eres la pesadilla que nos\\ndio la paliza!",
  ["Route8_Text_AidanRematchIntro"] = "Se te dan bien los POKéMON, pero\\n¿qué tal en química?",
  ["Route8_Text_AndreaRematchIntro"] = "¡MEOWTH y PERSIAN son ideales,\\nideales totales, meow, meow, meow!",
  ["Route8_Text_AnneRematchIntro"] = "LIN: ¡Ya somos mucho más fuertes!",
  ["Route8_Text_EliRematchIntro"] = "TITA: ¡Ahora somos más fuertes!",
  ["Route8_Text_GlennRematchIntro"] = "¡Necesitas una buena estrategia!\\p¿Te queda claro?",
  ["Route8_Text_JarenRematchIntro"] = "Bueno, esta vez no me voy\\na andar con tonterías.",
  ["Route8_Text_JuliaRematchIntro"] = "¿Qué POKéMON es mono, redondo\\ny blando?\\pLo sabes, ¿no?",
  ["Route8_Text_LeslieRematchIntro"] = "¡Me gusta el colegio y los\\nPOKéMON!",
  ["Route8_Text_MeganRematchIntro"] = "Debemos de dar una imagen algo\\ntonta, pero ¡lo importante es que\\lyo quiero luchar!",
  ["Route8_Text_PaigeRematchIntro"] = "Tengo muchos NIDORAN.\\nNo quiero que evolucionen, pero...",
  ["Route8_Text_RicardoRematchIntro"] = "¡Mi bici sigue yendo como\\nuna moto!",
  ["Route8_Text_RichRematchIntro"] = "¡Soy un jugador errante!\\n¡Y voy a ganar!",
  ["Route8_Text_StanRematchIntro"] = "¡Muy bien!\\n¡Luchemos otra vez!",
  ["Route9_Text_AlanRematchIntro"] = "¡Esta vez gano yo!",
  ["Route9_Text_AliciaRematchIntro"] = "¿Vamos a luchar de nuevo?\\n¡Pues esta vez, olvídate!",
  ["Route9_Text_BrentRematchIntro"] = "Cada día me levanto temprano para\\nentrenar a mis POKéMON capullo.",
  ["Route9_Text_BriceRematchIntro"] = "¡Jaja! ¡A ver lo fuerte que estás!",
  ["Route9_Text_CaitlinRematchIntro"] = "¡No te andes con contemplaciones!\\n¡Hay que ir a por todas!",
