  ["gOakSpeech_Text_AskPlayerGender"] = "Hola, ¿eres chico o chica?",
  ["gOakSpeech_Text_ConfirmRivalName"] = "Eh..., ¿era {RIVAL}?",
  ["gOakSpeech_Text_IStudyPokemon"] = "Para algunos, los POKéMON son\\nmascotas. Pero otros los usan\\lpara pelear.\\pEn cuanto a mí...\\pEstudio a los POKéMON como\\nprofesión.\\p",
  ["gOakSpeech_Text_IsInhabitedFarAndWide"] = "habitado por unas criaturas\\nllamadas POKéMON!\\p",
  ["gOakSpeech_Text_LetsGo"] = "¡{PLAYER}!\\p¡Tu propia leyenda POKéMON está\\na punto de comenzar!\\p¡Te espera un mundo de sueños y\\naventuras con los POKéMON!\\l¡Adelante!",
  ["gOakSpeech_Text_RememberRivalsName"] = "¡Ah, sí! ¡Es verdad!\\n¡Se llamaba {RIVAL}!\\p",
  ["gOakSpeech_Text_SoYourNameIsPlayer"] = "¡Bien!\\n¡Así que te llamas {PLAYER}!",
  ["gOakSpeech_Text_TellMeALittleAboutYourself"] = "Bueno, cuéntame algo de ti.\\p",
  ["gOakSpeech_Text_ThisWorld"] = "¡Este mundo está",
  ["gOakSpeech_Text_WelcomeToTheWorld"] = "¡Hola!\\n¡Éste es el mundo de POKéMON!\\p¡Me llamo OAK!\\p¡Pero la gente me llama\\nPROFESOR POKéMON!\\p",
  ["gOakSpeech_Text_WhatWasHisName"] = "Éste es mi nieto.\\pHa sido tu rival desde que erais\\npequeños.\\pMmm... ¿podrías decirme cómo\\nse llama?",
  ["gOakSpeech_Text_YourNameWhatIsIt"] = "Pero primero dime cómo te llamas.\\p\\n",
  ["gOakSpeech_Text_YourRivalsNameWhatWasIt"] = "¿Cómo era el nombre de tu rival?",
