  ["sStartMenuDescPointers[0]"] = "Contiene importantes datos de los\\nPKMN con los que te vas encontrando.",
  ["sStartMenuDescPointers[1]"] = "Aquí, entre otras cosas, puedes\\norganizar los PKMN de tu equipo.",
  ["sStartMenuDescPointers[2]"] = "Guarda en los bolsillos las cosas\\nque encuentres, compres o te den.",
  ["sStartMenuDescPointers[3]"] = "Aquí podrás ver algunos datos de\\ntu partida, como el dinero que llevas.",
  ["sStartMenuDescPointers[4]"] = "Guarda cuando quieras todos los datos\\nde tu partida para descansar un rato.",
  ["sStartMenuDescPointers[5]"] = "Si quieres cambiar la velocidad del\\ntexto, el sonido, etc., hazlo desde aquí.",
